<main class="main-content"><header class="topbar"><div><span class="eyebrow">LIBRARY CATALOGUE</span><h1>Authors</h1></div></header><section class="content-card"><?php flash_html();?><div class="section-heading"><div><h2>Authors register</h2><p>Maintain the catalogue reference records.</p></div><a class="btn" href="create.php">＋ Add author</a></div><form class="search-form"><input name="q" value="<?=e($q)?>" placeholder="Search authors"><button class="btn">Search</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Author</th><th>Country</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['author_name'])?></td><td><?=e($r['country']?:'—')?></td><td><a class="btn btn-small btn-secondary" href="edit.php?id=<?=(int)$r['author_id']?>">Edit</a> <form class="inline-form" method="post" action="delete.php" onsubmit="return confirm('Delete this record? Linked records may prevent deletion.');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['author_id']?>"><button class="btn btn-small btn-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="3" class="empty-state">No records found.</td></tr><?php endif;?></tbody></table></div></section></main><?php require __DIR__.'/../includes/footer.php';?>